/** The regular expressions of the Less namespace, kept as `lib/regexps.ts` keeps the core's. */
/** A Less `:extend`, with or without its selector list. */
export declare const LESS_EXTEND: RegExp;
/** A Less `:extend(…)` with a selector list, in any case. */
export declare const LESS_EXTEND_CALL: RegExp;
/** A name Less calls a detached ruleset by: its `variableCall` reads ASCII word characters and hyphens, and an at-rule of the same shape spelling any other is read as an at-rule. */
export declare const LESS_DETACHED_RULESET_NAME: RegExp;
/** The `when` of a Less guard, lower case only, as Less reads its keywords. */
export declare const LESS_GUARD: RegExp;
/** The head of a Less mixin definition's selector: one class or id name, escapes included, and the parenthesis opening its parameter list, whitespace allowed in front; the pattern Less's `mixin.definition` reads, but for an escaped character outside the Basic Multilingual Plane, which this reads whole and Less refuses. */
export declare const LESS_MIXIN_DEFINITION_HEAD: RegExp;
/** An option Less reads in the parentheses between `@import` and its address, as its `importOption` reads one: the word at the start of the text, whatever follows it. */
export declare const LESS_IMPORT_OPTION: RegExp;
/** The arguments Less reads in the parentheses between `@plugin` and its address, as its `pluginArgs` reads them: everything up to the closing parenthesis, one character at least, no semicolon. */
export declare const LESS_PLUGIN_ARGUMENTS: RegExp;
/** The whitespace Less asks for right behind the name of an `@import` or a `@plugin`, as its `\s+` there reads one. */
export declare const LESS_LEADING_WHITESPACE: RegExp;
/** A character Less's `skipWhitespace` steps over between the tokens of such a group. */
export declare const LESS_SKIPPED_WHITESPACE: RegExp;
/** The parameter list closing a Less parametric mixin's selector. */
export declare const LESS_PARAMETRIC_MIXIN: RegExp;
/** A Less mixin call with something behind it, as `.foo().bar` is. */
export declare const LESS_RESOLVED_MIXIN: RegExp;
/** A single entity, no call, a Less custom property's value may spell alone in front of a `//` comment and still have `permissiveValue` read that comment whole: a bare word, a quoted string, or a bracketed group. */
export declare const LESS_CUSTOM_PROPERTY_BARE_ENTITY: RegExp;
/** A call's name and opening parenthesis, at the start of a text. */
export declare const LESS_CALL_OPENING: RegExp;
